 [Serializable]public sealed class FileProof {public string Path,Sha256;}
 [Serializable]public sealed class ArchiveRow {public string source,archive,sha256;public bool verified;}
 [Serializable]public sealed class ArchiveRows {public ArchiveRow[] rows;}
 [Serializable]public sealed class CheckpointProof {public string Batch,SourceDirectory,RunId,ContentVersion,FinalRootPath,FinalRootSha256,ReportPath,ReportSha256,BatchManifestPath,BatchManifestSha256;public FileProof[] Files;}
 private static string Hash(string p){using(var sha=SHA256.Create())using(var stream=File.OpenRead(p))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");}
 private static string CloneCheckpoint(string proofPath,string destination,out CheckpointProof proof){
  proof=JsonUtility.FromJson<CheckpointProof>(File.ReadAllText(proofPath));Assert.That(proof.Batch,Is.Not.Null.And.Not.Empty);Assert.That(proof.RunId,Is.Not.Null.And.Not.Empty);
  Assert.That(Hash(proof.BatchManifestPath),Is.EqualTo(proof.BatchManifestSha256));
  Assert.That(new DirectoryInfo(Path.GetDirectoryName(proof.BatchManifestPath)).Name,Is.EqualTo(proof.Batch));
  var archive=JsonUtility.FromJson<ArchiveRows>("{\"rows\":"+File.ReadAllText(proof.BatchManifestPath)+"}").rows;
  foreach(var pair in new[]{new[]{proof.ReportPath,proof.ReportSha256},new[]{proof.FinalRootPath,proof.FinalRootSha256}})Assert.That(archive.Any(r=>r.verified&&r.sha256==pair[1]&&(Path.GetFullPath(r.archive)==Path.GetFullPath(pair[0])||Path.GetFullPath(r.source)==Path.GetFullPath(pair[0]))),Is.True,"Source evidence must belong to declared verified archive batch");
  Assert.That(Hash(proof.FinalRootPath),Is.EqualTo(proof.FinalRootSha256));Assert.That(Hash(proof.ReportPath),Is.EqualTo(proof.ReportSha256));
  Assert.That(File.ReadAllLines(proof.ReportPath).Contains("outcome=NaturalRomanceContinued"),Is.True,"Source batch must be a sealed natural romance continuation");
  string root=Path.GetFullPath(proof.SourceDirectory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
  var actual=Directory.GetFiles(root,"*",SearchOption.AllDirectories).Select(p=>p.Substring(root.Length).Replace('\\','/')).OrderBy(p=>p).ToArray();Assert.That(proof.Files.Select(f=>f.Path).OrderBy(p=>p).ToArray(),Is.EqualTo(actual),"Proof must list entire sealed save");Directory.CreateDirectory(destination);
  foreach(var f in proof.Files){string source=Path.GetFullPath(Path.Combine(root,f.Path));Assert.That(source.StartsWith(root,StringComparison.OrdinalIgnoreCase),Is.True);Assert.That(Hash(source),Is.EqualTo(f.Sha256));string output=Path.Combine(destination,f.Path);Directory.CreateDirectory(Path.GetDirectoryName(output));AutomationEvidence.Copy(source,output,false);Assert.That(Hash(output),Is.EqualTo(f.Sha256));}
  return Hash(proofPath);
 }
 private static T Read<T>(GameSession s,string owner)=>JsonUtility.FromJson<T>(s.InspectSnapshot().FindFragment(owner,"player").Json);
 private static string HistoryJson(AchievementHistoryEntry h)=>JsonUtility.ToJson(h.Snapshot)+"\n"+h.NoteState+"\n"+h.Note;
 private static string PermanentJson(GameSession s)=>s.InspectSnapshot().PermanentFragments.Single(f=>f.Owner=="progression"&&f.Scope=="permanent").Json;
 [Serializable] private sealed class WorldStamp { public int Day;public string Phase,BarrierId; }
 private static RootEnvelope ObserveFreeze(GameSession s,RootEnvelope ready,ref bool verified,int ordinal,int contestDay){
  var root=s.InspectSnapshot();if(root==null)return ready;var sf=root.FindFragment("session","player");if(sf==null)return ready;
  var state=JsonUtility.FromJson<SessionState>(sf.Json);if(state.Day!=contestDay)return ready;
  var c=JsonUtility.FromJson<CompetitionState>(root.FindFragment("competition","player").Json);
  Assert.That(c.Current.Ordinal,Is.EqualTo(ordinal));Assert.That(c.Current.ContestDay,Is.EqualTo(contestDay));
  var wf=root.FindFragment("world","shared");var world=wf==null?null:JsonUtility.FromJson<WorldStamp>(wf.Json);
  if(c.Current.FrozenActors.Length==0&&world!=null&&world.Day==contestDay&&world.Phase=="DayOpenReady"){
   foreach(string actor in new[]{"player","rival","beginner","veteran","coach"}){var actorState=JsonUtility.FromJson<SessionState>(root.FindFragment("session",actor).Json);Assert.That(actorState.Day,Is.EqualTo(contestDay));Assert.That(actorState.Phase,Is.EqualTo("DayOpenReady"));}
   return JsonUtility.FromJson<RootEnvelope>(JsonUtility.ToJson(root));
  }
  if(!verified&&c.Current.FrozenActors.Length>0){Assert.That(ready,Is.Not.Null,"Missing observed pre-freeze committed barrier");Assert.That(c.Current.BarrierId,Is.EqualTo(JsonUtility.FromJson<WorldStamp>(ready.FindFragment("world","shared").Json).BarrierId));Assert.That(c.Current.FrozenActors.Select(x=>x.ActorId).OrderBy(x=>x).ToArray(),Is.EqualTo(new[]{"player","rival"}));foreach(var actor in c.Current.FrozenActors){var body=JsonUtility.FromJson<FitnessSimulator.Game.Body.BodyState>(ready.FindFragment("body",actor.ActorId).Json);Assert.That(actor.Day,Is.EqualTo(contestDay));Assert.That(actor.Phase,Is.EqualTo("DayOpenReady"));Assert.That(actor.SourceCommitId,Is.EqualTo(ready.LastCommitId));Assert.That(actor.ActorRevision,Is.EqualTo(body.Revision));Assert.That(actor.SourceKind,Is.EqualTo(actor.ActorId=="player"?CompetitionSourceKind.PlayerProduction:CompetitionSourceKind.NpcProduction));Assert.That(root.FindFragment("body",actor.ActorId).Json,Is.EqualTo(ready.FindFragment("body",actor.ActorId).Json));Assert.That(JsonUtility.ToJson(actor.Body),Is.EqualTo(JsonUtility.ToJson(body)));}verified=true;}
  return ready;
 }
 private sealed class Driver:IDisposable {
  public GameSession S;public readonly string DirectoryPath,Save;public readonly Stopwatch Watch=Stopwatch.StartNew();public readonly int Seconds;
  public int Commands,Inputs,Clocks,Steps;public int MaxDay=43,TargetOrdinal,TargetContestDay;public int Day=8;public bool NeedsRest;public string Outcome="BudgetExhausted",Error="";
  private readonly string prefix="romance-obligation/"+Guid.NewGuid().ToString("N")+"/";private readonly EvidenceTrace writer;
  public Driver(string dir,int seconds){DirectoryPath=dir;Save=Path.Combine(dir,"save");Seconds=seconds;S=AutomationEvidenceSession.OpenAutomation(Save,1);writer=new EvidenceTrace(Path.Combine(dir,"trace.jsonl"));}
  public void Log(string line){if(Watch.Elapsed.TotalSeconds>Seconds)throw new InvalidOperationException("WallBudgetExceeded");if(line.StartsWith("advance-ms="))Clocks++;if(line.Contains("\"ActionId\":\"training-input\""))Inputs++;writer.WriteLine(line);}
  public FrontendView View(){if(++Steps>500000)throw new InvalidOperationException("OuterStepBudgetExceeded");var v=S.ReadView();Log(JsonUtility.ToJson(v));Assert.That(v.ScreenId,Is.Not.EqualTo("error"),v.Body);var m=System.Text.RegularExpressions.Regex.Match(v.Status??"",@"第\s*(\d+)\s*日");if(m.Success)Day=int.Parse(m.Groups[1].Value);Assert.That(Day,Is.LessThanOrEqualTo(MaxDay));if(v.ScreenId.StartsWith("summary/"))NeedsRest=false;return v;}
  public void Send(FrontendOption o){var v=S.ReadView();var a=new FrontendAction{RunId=v.RunId,ExpectedRevision=v.Revision,OperationId=prefix+(++Commands),ActionId=o.Id,StringValue=o.StringValue,IntValue=o.IntValue};Log(JsonUtility.ToJson(v));Log(JsonUtility.ToJson(a));var r=AutomationEvidenceSession.Execute(S,a);Log(JsonUtility.ToJson(r));Assert.That(r.Accepted,Is.True,r.Message);if(o.Id=="settle")NeedsRest=true;if(o.Id=="competition-enroll"||o.Id=="competition-attend"||o.Id=="competition-decline"||o.Id=="ending-continue"||o.Id=="ending-empty"){string root=JsonUtility.ToJson(S.InspectSnapshot());Assert.That(AutomationEvidenceSession.Execute(S,a).Accepted,Is.True);Assert.That(JsonUtility.ToJson(S.InspectSnapshot()),Is.EqualTo(root));}}
  public bool Normal(FrontendView v,bool bodybuilding){var options=v.Actions.Where(a=>a.Enabled).ToArray();FrontendOption o=null;
   if(v.TrainingInput!=null){Assert.That(PublicEightInputDriver.DriveActiveSet(S,v.TrainingInput.ExerciseId,Log),Is.EqualTo("AwaitProductionResult"));return true;}
   if(options.Any(a=>a.Id=="begin-set")){if(NeedsRest){o=options.First(a=>a.Id=="rest"&&a.IntValue==180);Send(o);NeedsRest=false;return true;}bool first=System.Text.RegularExpressions.Regex.IsMatch(v.Body??"",@"第\s*1\s*组");o=bodybuilding&&first?options.FirstOrDefault(a=>a.Id=="begin-set"&&a.IntValue==1):null;o=o??options.FirstOrDefault(a=>a.Id=="begin-set"&&a.StringValue=="auto")??options.First(a=>a.Id=="begin-set"&&a.StringValue=="manual"&&a.IntValue==0);}
   if(o==null&&options.Any(a=>a.Id=="choose-entry"))o=options.FirstOrDefault(a=>a.Id=="choose-entry"&&a.StringValue=="training-choice")??options.First(a=>a.Id=="choose-entry");
   if(o==null&&options.Any(a=>a.Id=="meal")){o=options.FirstOrDefault(a=>a.Id=="meal"&&new[]{"porridge_egg","home_rice","home_noodles"}.Contains(a.StringValue));Assert.That(o,Is.Not.Null,"CoverageMissing: paid meal unavailable");}
   foreach(var id in new[]{"continue-game","ending-segment","ending-empty","settle","continue","shop-leave","item-use","competition-next","next-day"})if(o==null)o=options.FirstOrDefault(a=>a.Id==id);
   if(o!=null){Send(o);return true;}var unknown=options.FirstOrDefault(a=>!new[]{"save-plan","open-menu","competition-menu","history-open","new-game"}.Contains(a.Id));Assert.That(unknown,Is.Null,"MissingHandler: "+v.ScreenId+"/"+unknown?.Id);Log("advance-ms=0");S.Advance(0);return true;
  }
  public System.Collections.Generic.List<AchievementHistoryEntry> History(){string root=JsonUtility.ToJson(S.InspectSnapshot());S.Dispose();System.Collections.Generic.List<AchievementHistoryEntry> entries;using(var store=new LocalCheckpointStore(Save,new UnityJsonStateCodec())){store.Load();entries=new EndingProgression(new UnityJsonStateCodec()).ReadHistory(store,0,64);}S=AutomationEvidenceSession.OpenAutomation(Save,1);Assert.That(JsonUtility.ToJson(S.InspectSnapshot()),Is.EqualTo(root));return entries;}
  public void Dispose(){writer.Flush();AutomationEvidence.WriteAllText(Path.Combine(DirectoryPath,"final.json"),JsonUtility.ToJson(S.InspectSnapshot(),true));AutomationEvidence.WriteAllText(Path.Combine(DirectoryPath,"report.txt"),"outcome="+Outcome+"\nexception="+Error+"\nmaxSeconds="+Seconds+"\nelapsedSeconds="+Watch.Elapsed.TotalSeconds+"\ntargetOrdinal="+TargetOrdinal+"\ntargetContestDay="+TargetContestDay+"\nmaxDay="+MaxDay+"\nmaxSteps=500000\nsteps="+Steps+"\nbusinessCommands="+Commands+"\ninputEdges="+Inputs+"\nclockCalls="+Clocks+"\nevidenceByteLimit="+AutomationEvidence.TraceLimit+"\nevidenceBytes="+writer.Bytes);S.Dispose();writer.Dispose();}
 }
 [TestCase(true),TestCase(false),Explicit("Requires sealed actual NaturalRomanceContinued source"),Timeout(3660000)]
 public void NaturalRomanceStillRequiresCompetition(bool attendThin){
  string proofPath=Environment.GetEnvironmentVariable("FITNESS_ROMANCE_OBLIGATION_PROOF");Assert.That(File.Exists(proofPath),Is.True,"CoverageMissing: actual sealed romance source not yet supplied");int seconds=int.Parse(Environment.GetEnvironmentVariable("FITNESS_ROMANCE_OBLIGATION_SECONDS")??throw new InvalidOperationException("Explicit branch budget required"));Assert.That(seconds,Is.InRange(1,3600));
  string dir=Path.Combine(AutomationEvidence.OutputRoot,"Fitness-Romance-Obligations",(attendThin?"attend-":"zero-")+Guid.NewGuid().ToString("N"));AutomationEvidence.RegisterDirectory(dir);TestContext.WriteLine(dir);CheckpointProof proof;string proofHash=CloneCheckpoint(proofPath,Path.Combine(dir,"save"),out proof);AutomationEvidence.Copy(proofPath,Path.Combine(dir,"source-proof.json"));AutomationEvidence.WriteAllText(Path.Combine(dir,"source-binding.txt"),"batch="+proof.Batch+"\nproofSha256="+proofHash+"\nrunId="+proof.RunId+"\nreportSha256="+proof.ReportSha256+"\nfinalSha256="+proof.FinalRootSha256+"\ncurrentGameAssemblySha256="+Hash(typeof(GameSession).Assembly.Location));
  using(var d=new Driver(dir,seconds)){try{
   var source=d.S.InspectSnapshot();Assert.That(JsonUtility.ToJson(source),Is.EqualTo(JsonUtility.ToJson(JsonUtility.FromJson<RootEnvelope>(File.ReadAllText(proof.FinalRootPath)))));Assert.That(source.RunId,Is.EqualTo(proof.RunId));Assert.That(source.ContentVersion,Is.EqualTo(proof.ContentVersion));
   var initial=Read<CompetitionState>(d.S,"competition");var initialSession=Read<SessionState>(d.S,"session");
   int targetOrdinal=initial.Current.Ordinal,targetDay=initial.Current.ContestDay;d.TargetOrdinal=targetOrdinal;d.TargetContestDay=targetDay;d.MaxDay=targetDay+1;d.Day=initialSession.Day;
   if(initialSession.Day>targetDay||initial.Current.ActualAttendanceCount!=0||initial.Current.Facts.Length!=0||initial.Current.Contests.Any(c=>c.WindowClosed||c.Results.Length!=0))throw new InvalidOperationException("CoverageMissing: source is not same-edition pre-window zero-attendance state; cannot substitute a later edition");
   if(initial.Current.FrozenActors.Length!=0)throw new InvalidOperationException("CoverageMissing: source already frozen; this candidate requires observable committed pre-freeze barrier");
   bool registrationObserved=initial.Current.Contest(ContestKind.ThinBuild).Enrolled;int registrationMenuDay=0;
   Assert.That(Read<FitnessSimulator.Game.Life.Relationships.RelationshipState>(d.S,"relationships").RomanceEstablished,Is.True);var pr=Read<ProgressionRun>(d.S,"progression");Assert.That(pr.TerminalLock,Is.False);Assert.That(pr.TriggeredEndingIds.Count(x=>x=="romance_success"),Is.EqualTo(1));
   var history=d.History();Assert.That(history.Select(h=>h.Snapshot.AchievementId).Distinct().Count(),Is.EqualTo(history.Count));var romance=history.Single(h=>h.Snapshot.RunId==proof.RunId&&h.Snapshot.EndingId=="romance_success");Assert.That(romance.Snapshot.Day,Is.InRange(targetDay-41,targetDay),"CoverageMissing: source current edition is not the edition of actual romance success");Assert.That(romance.Snapshot.Terminal,Is.False);Assert.That(romance.NoteState,Is.Not.EqualTo(AchievementNoteState.Pending));string romanceId=romance.Snapshot.AchievementId,romanceRecord=HistoryJson(romance);var old=history.ToDictionary(h=>h.Snapshot.AchievementId,HistoryJson);string permanentBefore=PermanentJson(d.S);var grants=JsonUtility.FromJson<ProgressionPermanent>(permanentBefore);var lean=grants.TemplateGrants.Single(g=>g.TemplateId=="lean_social");var grantSource=history.Single(h=>h.Snapshot.AchievementId==lean.AchievementId);Assert.That(grantSource.Snapshot.RunId,Is.EqualTo(proof.RunId));Assert.That(grantSource.Snapshot.Terminal,Is.False);Assert.That(new[]{"romance_success","lean_champion"},Does.Contain(grantSource.Snapshot.EndingId));
   bool alreadyLeanChampion=history.Any(h=>h.Snapshot.RunId==proof.RunId&&h.Snapshot.EndingId=="lean_champion");
   RootEnvelope ready=null;bool freezeVerified=false,attended=false,won=false,finished=false,continued=false,zeroFinalDecision=false;string newEndingId=null,newAchievement=null;string actualScore=null;
   for(;;){ready=ObserveFreeze(d.S,ready,ref freezeVerified,targetOrdinal,targetDay);var v=d.View();var options=v.Actions.Where(a=>a.Enabled).ToArray();
    if(!attendThin&&!zeroFinalDecision){Assert.That(Read<CompetitionState>(d.S,"competition").Current.Facts.Any(f=>f.Kind==CompetitionFactKind.Unfulfilled),Is.False,"Unfulfilled before explicit afternoon decision");Assert.That(Read<ProgressionRun>(d.S,"progression").TerminalLock,Is.False,"Terminal before explicit afternoon decision");}
    if(d.Day==targetDay+1&&Read<CompetitionState>(d.S,"competition").Current.Ordinal==targetOrdinal+1){Assert.That(attendThin&&attended&&won&&(continued||alreadyLeanChampion),Is.True);var next=Read<CompetitionState>(d.S,"competition").Current;Assert.That(next.ContestDay,Is.EqualTo(targetDay+42));Assert.That(next.ActualAttendanceCount,Is.Zero);Assert.That(next.Facts,Is.Empty);Assert.That(next.FrozenActors,Is.Empty);Assert.That(next.Contests.All(c=>!c.Enrolled&&c.JudgeIds.Length==0&&c.Results.Length==0),Is.True);finished=true;d.Outcome="RomanceActualChampionContinuedNextEdition";break;}
    if(v.ScreenId=="ending-menu"&&!options.Any(a=>a.Id=="ending-continue")){var terminal=Read<ProgressionRun>(d.S,"progression");Assert.That(terminal.TerminalLock,Is.True);newEndingId=attendThin?"competition_failed":"competition_unfulfilled";Assert.That(terminal.Active.EndingId,Is.EqualTo(newEndingId));Assert.That(terminal.Active.NoteState,Is.EqualTo(AchievementNoteState.CommittedEmpty));newAchievement=terminal.Active.AchievementId;Assert.That(attendThin?attended&&!won:!attended&&zeroFinalDecision,Is.True,"Zero attendance terminal requires accepted afternoon decline");finished=true;d.Outcome=attendThin?"RomanceActualAttendanceNonChampionTerminal":"RomanceZeroAttendanceUnfulfilledTerminal";break;}
    var resume=options.FirstOrDefault(a=>a.Id=="ending-continue");if(resume!=null){Assert.That(attendThin&&attended&&won,Is.True,"Unexpected success before actual attendance");Assert.That(alreadyLeanChampion,Is.False,"Already-earned champion must not replay success ending");var success=Read<ProgressionRun>(d.S,"progression");Assert.That(success.Active.EndingId,Is.EqualTo("lean_champion"));newEndingId=success.Active.EndingId;newAchievement=success.Active.AchievementId;var normal=d.S.InspectSnapshot().Fragments.Where(f=>f.Owner!="progression").ToDictionary(f=>f.Owner.Length+":"+f.Owner+f.Scope.Length+":"+f.Scope,f=>JsonUtility.ToJson(f));d.Send(resume);Assert.That(d.S.InspectSnapshot().Fragments.Count(f=>f.Owner!="progression"),Is.EqualTo(normal.Count));foreach(var f in d.S.InspectSnapshot().Fragments.Where(f=>f.Owner!="progression"))Assert.That(JsonUtility.ToJson(f),Is.EqualTo(normal[f.Owner.Length+":"+f.Owner+f.Scope.Length+":"+f.Scope]));d.History();continued=true;continue;}
    if(!registrationObserved&&registrationMenuDay!=d.Day){var menu=options.FirstOrDefault(a=>a.Id=="competition-menu");if(menu!=null){registrationMenuDay=d.Day;d.Send(menu);continue;}}
    if(v.ScreenId=="competition"){
     var enroll=options.FirstOrDefault(a=>a.Id=="competition-enroll"&&a.IntValue==1);if(!registrationObserved&&enroll!=null){d.Send(enroll);registrationObserved=true;Assert.That(Read<CompetitionState>(d.S,"competition").Current.Contest(ContestKind.ThinBuild).Enrolled,Is.True);continue;}
     var morning=options.FirstOrDefault(a=>a.Id=="competition-decline"&&a.IntValue==0);if(morning!=null){d.Send(morning);if(!attendThin){Assert.That(Read<CompetitionState>(d.S,"competition").Current.Facts.Any(f=>f.Kind==CompetitionFactKind.Unfulfilled),Is.False,"Morning decline must not fulfill the terminal condition");Assert.That(Read<ProgressionRun>(d.S,"progression").TerminalLock,Is.False);}Assert.That(Read<CompetitionState>(d.S,"competition").Current.Contest(ContestKind.ThinBuild).Results,Is.Empty);continue;}
     var target=options.FirstOrDefault(a=>a.IntValue==1&&a.Id==(attendThin?"competition-attend":"competition-decline"));if(target!=null){Assert.That(registrationObserved,Is.True,"CoverageMissing: no accepted thin registration before target window");Assert.That(Read<CompetitionState>(d.S,"competition").Current.Contest(ContestKind.ThinBuild).Enrolled,Is.True);Assert.That(freezeVerified,Is.True);d.Send(target);var c=Read<CompetitionState>(d.S,"competition");if(attendThin){attended=true;Assert.That(c.Current.ActualAttendanceCount,Is.EqualTo(1));NaturalChampionRouteTests.AuditScores(d.S,ContestKind.ThinBuild,false);var result=c.Current.Contest(ContestKind.ThinBuild).Results.Single();won=result.Score.Participants.Single(p=>p.ActorId==c.PlayerId).Rank==1;actualScore=JsonUtility.ToJson(result);Assert.That(c.Current.Facts.Count(f=>f.Kind==(won?CompetitionFactKind.Champion:CompetitionFactKind.NonChampion)),Is.EqualTo(1));}else{zeroFinalDecision=true;Assert.That(c.Current.Contest(ContestKind.ThinBuild).Declined,Is.True);Assert.That(c.Current.ActualAttendanceCount,Is.Zero);Assert.That(c.Current.Facts.Count(f=>f.Kind==CompetitionFactKind.Unfulfilled),Is.EqualTo(1));Assert.That(c.Current.Facts.Any(f=>f.Kind==CompetitionFactKind.NonChampion),Is.False);Assert.That(c.Current.Contests.All(x=>x.Results.Length==0),Is.True);}continue;}
     var close=options.FirstOrDefault(a=>a.Id=="competition-close");if(close!=null){d.Send(close);continue;}
    }
    d.Normal(v,false);
   }
   Assert.That(finished&&freezeVerified,Is.True);Assert.That(d.S.InspectSnapshot().RunId,Is.EqualTo(proof.RunId));Assert.That(Read<FitnessSimulator.Game.Life.Relationships.RelationshipState>(d.S,"relationships").RomanceEstablished,Is.True);Assert.That(PermanentJson(d.S),Is.EqualTo(permanentBefore),"Existing lean_social grant and its original achievement must remain exact; no new grant");var finalCompetition=Read<CompetitionState>(d.S,"competition").Editions.Single(e=>e.Ordinal==targetOrdinal);Assert.That(finalCompetition.ActualAttendanceCount,Is.EqualTo(attendThin?1:0));if(attendThin)Assert.That(JsonUtility.ToJson(finalCompetition.Contest(ContestKind.ThinBuild).Results.Single()),Is.EqualTo(actualScore));else{Assert.That(finalCompetition.Contests.All(c=>c.WindowClosed&&c.Results.Length==0),Is.True);Assert.That(zeroFinalDecision,Is.True);Assert.That(finalCompetition.Facts.Count(f=>f.Kind==CompetitionFactKind.Unfulfilled),Is.EqualTo(1));Assert.That(finalCompetition.Facts.Any(f=>f.Kind==CompetitionFactKind.NonChampion),Is.False);}
   var finalHistory=d.History();foreach(var pair in old)Assert.That(HistoryJson(finalHistory.Single(h=>h.Snapshot.AchievementId==pair.Key)),Is.EqualTo(pair.Value));Assert.That(HistoryJson(finalHistory.Single(h=>h.Snapshot.AchievementId==romanceId)),Is.EqualTo(romanceRecord));Assert.That(finalHistory.Count(h=>h.Snapshot.RunId==proof.RunId&&h.Snapshot.EndingId=="romance_success"),Is.EqualTo(1));if(attendThin&&won&&alreadyLeanChampion){Assert.That(finalHistory.Count,Is.EqualTo(old.Count));Assert.That(newAchievement,Is.Null);Assert.That(continued,Is.False);}else{Assert.That(finalHistory.Count,Is.EqualTo(old.Count+1));var added=finalHistory.Single(h=>h.Snapshot.AchievementId==newAchievement);Assert.That(added.Snapshot.RunId,Is.EqualTo(proof.RunId));Assert.That(added.Snapshot.Day,Is.EqualTo(targetDay));Assert.That(added.Snapshot.EndingId,Is.EqualTo(newEndingId));Assert.That(added.Snapshot.Terminal,Is.EqualTo(!attendThin||!won));Assert.That(added.NoteState,Is.EqualTo(AchievementNoteState.CommittedEmpty));Assert.That(added.Note,Is.Empty);}if(!attendThin||!won){Assert.That(Read<ProgressionRun>(d.S,"progression").TerminalLock,Is.True);Assert.That(d.S.ReadView().Actions.Any(a=>a.Enabled&&a.Id=="ending-continue"),Is.False);}
  }catch(Exception e){d.Error=e.ToString();d.Outcome=e.Message.Contains("CoverageMissing")?"CoverageMissing":"AssertionOrBudgetFailure";throw;}}
 }
}
